<script setup>
import { computed } from 'vue';
const props = defineProps({ selection: { type: Array, default: () => [] }, kit: Object, fonts: { type: Array, default: () => [] }, imageBusy: Boolean });
const emit = defineEmits(['patch', 'action', 'remove-background', 'edit-chart']);
const item = computed(() => props.selection[0]);
const patch = (key, value) => emit('patch', { [key]: value });
const numeric = (key, event) => { const value = Number(event.target.value); if (Number.isFinite(value) && event.target.value !== '') patch(key, value); };
const solid = computed(() => typeof item.value?.fill === 'string' ? item.value.fill : item.value?.fill?.stops?.[0]?.color ?? '#7c3aed');
const gradient = (field, value) => {
    const existing = typeof item.value.fill === 'object' ? JSON.parse(JSON.stringify(item.value.fill)) : { type: 'linear', angle: 45, stops: [{ offset: 0, color: solid.value }, { offset: 1, color: '#ffffff' }] };
    if (field === 'angle') existing.angle = Number(value);
    else existing.stops[field === 'start' ? 0 : existing.stops.length - 1].color = value;
    patch('fill', existing);
};
const shadow = (key, value) => patch('shadow', { color: '#00000066', blur: 12, offsetX: 0, offsetY: 4, ...item.value.shadow, [key]: value });
const filter = (key, value) => patch('filters', { ...item.value.filters, [key]: value });
const table = computed(() => item.value?.type === 'table' ? item.value.table : null);
const tableRows = computed(() => table.value?.rows.length ?? 0);
const tableCols = computed(() => table.value?.rows[0]?.length ?? 0);
const patchTable = change => patch('table', { ...item.value.table, ...change });
const editCell = (r, c, value) => patchTable({ rows: item.value.table.rows.map((row, i) => i === r ? row.map((cell, j) => j === c ? value : cell) : row) });
const addRow = () => tableRows.value < 30 && patchTable({ rows: [...item.value.table.rows, Array(tableCols.value).fill('')] });
const removeRow = () => tableRows.value > 1 && patchTable({ rows: item.value.table.rows.slice(0, -1) });
const addColumn = () => tableCols.value < 12 && patchTable({ rows: item.value.table.rows.map(row => [...row, '']) });
const removeColumn = () => tableCols.value > 1 && patchTable({ rows: item.value.table.rows.map(row => row.slice(0, -1)) });
const colors = computed(() => props.kit?.palette ?? []);
const localFamilies = computed(() => [...new Set(['Arial', 'Georgia', 'Verdana', 'Trebuchet MS', 'Times New Roman', ...(props.kit?.fonts ?? []), ...(item.value?.font_id ? [] : [item.value?.fontFamily])].filter(Boolean))]);
const fontChoices = computed(() => props.fonts.filter(font => !font.archived_at || font.id === item.value?.font_id));
const fontValue = computed(() => item.value?.font_id ? `font:${item.value.font_id}` : `local:${item.value?.fontFamily ?? 'Arial'}`);
function chooseFont(value) {
    if (value.startsWith('font:')) {
        const font = props.fonts.find(entry => entry.id === Number(value.slice(5)));
        if (font) emit('patch', { font_id: font.id, fontFamily: font.family, fontStyle: font.style === 'italic' ? 'italic' : 'normal', fontWeight: font.weight >= 600 ? 'bold' : 'normal' });
    } else emit('patch', { font_id: null, fontFamily: value.slice(6) });
}
function chooseMask(type) {
    patch('mask', type === 'none' ? null : type === 'ellipse' ? { type } : { type, radius: Math.min(24, item.value.width / 2, item.value.height / 2) });
}
</script>
<template>
    <section aria-label="Propiedades del elemento" class="space-y-5 text-xs">
        <h2 class="text-sm font-semibold">{{ selection.length > 1 ? `${selection.length} elementos seleccionados` : 'Propiedades' }}</h2>
        <p v-if="!item" class="rounded-xl border border-dashed border-slate-200 p-5 leading-relaxed text-slate-500">Selecciona un elemento en el lienzo o en Capas para editarlo.</p>
        <template v-else>
            <label class="block space-y-1 font-medium">Nombre de la capa<input class="field text-xs" :value="item.name" maxlength="255" @change="patch('name', $event.target.value)" /></label>
            <p v-if="item.locked" class="rounded-lg bg-amber-50 p-3 text-amber-800">Este elemento está bloqueado. <button type="button" class="font-semibold underline" @click="patch('locked', false)">Desbloquear</button></p>
            <fieldset :disabled="item.locked" class="space-y-5 disabled:opacity-50">
                <template v-if="item.type === 'text'">
                    <label class="block space-y-1 font-medium">Contenido del texto<textarea class="field text-xs" :value="item.text" rows="4" maxlength="10000" @input="patch('text', $event.target.value)" /></label>
                    <label class="block space-y-1 font-medium">Tipografía del texto<select class="field text-xs" aria-label="Tipografía del texto" :value="fontValue" @change="chooseFont($event.target.value)"><optgroup label="Fuentes locales"><option v-for="family in localFamilies" :key="family" :value="`local:${family}`">{{ family }}</option></optgroup><optgroup v-if="fontChoices.length" label="Archivos de esta marca"><option v-for="font in fontChoices" :key="font.id" :value="`font:${font.id}`">{{ font.name }} · {{ font.style }} {{ font.weight }}{{ font.archived_at ? ' · Archivada' : '' }}</option></optgroup></select></label>
                    <p v-if="item.font_id" class="text-[10px] leading-relaxed text-violet-700">Este texto utiliza un archivo tipográfico de la marca, también en sus exportaciones.</p>
                    <div class="grid grid-cols-2 gap-2"><label class="space-y-1">Tamaño de letra<input type="number" class="field text-xs" :value="item.fontSize" min="1" max="1000" @change="numeric('fontSize', $event)" /></label><label class="space-y-1">Alineación del texto<select class="field text-xs" :value="item.textAlign" @change="patch('textAlign', $event.target.value)"><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option><option value="justify">Justificado</option></select></label></div>
                    <div class="flex gap-2"><button type="button" class="toggle font-bold" :aria-pressed="item.fontWeight === 'bold'" @click="patch('fontWeight', item.fontWeight === 'bold' ? 'normal' : 'bold')">Negrita</button><button type="button" class="toggle italic" :aria-pressed="item.fontStyle === 'italic'" @click="patch('fontStyle', item.fontStyle === 'italic' ? 'normal' : 'italic')">Cursiva</button><button type="button" class="toggle underline" :aria-pressed="item.underline" @click="patch('underline', !item.underline)">Subrayado</button></div>
                    <div class="grid grid-cols-2 gap-2"><label class="space-y-1">Interlineado<input class="field text-xs" type="number" min="0.5" max="5" step="0.1" :value="item.lineHeight" @change="numeric('lineHeight', $event)" /></label><label class="space-y-1">Espaciado<input class="field text-xs" type="number" min="-200" max="2000" :value="item.charSpacing" @change="numeric('charSpacing', $event)" /></label></div>
                </template>
                <section v-if="table" class="space-y-3 rounded-xl border border-slate-200 p-3" aria-label="Tabla">
                    <h3 class="font-semibold">Tabla · {{ tableRows }} filas × {{ tableCols }} columnas</h3>
                    <div class="max-h-64 overflow-auto"><table class="w-full border-collapse text-xs"><tbody><tr v-for="(row, r) in table.rows" :key="r"><td v-for="(cell, c) in row" :key="c" class="p-0.5"><input class="field w-full min-w-16 text-xs" :value="cell" maxlength="500" :aria-label="`Celda fila ${r + 1} columna ${c + 1}`" @change="editCell(r, c, $event.target.value)" /></td></tr></tbody></table></div>
                    <div class="grid grid-cols-2 gap-2"><button type="button" class="toggle" :disabled="tableRows >= 30" @click="addRow">Añadir fila</button><button type="button" class="toggle" :disabled="tableRows <= 1" @click="removeRow">Quitar fila</button><button type="button" class="toggle" :disabled="tableCols >= 12" @click="addColumn">Añadir columna</button><button type="button" class="toggle" :disabled="tableCols <= 1" @click="removeColumn">Quitar columna</button></div>
                    <label class="flex items-center gap-2"><input type="checkbox" :checked="table.header" @change="patchTable({ header: $event.target.checked })" />Primera fila como encabezado</label>
                    <div class="grid grid-cols-2 gap-2"><label class="space-y-1">Tamaño de letra de la tabla<input type="number" class="field text-xs" aria-label="Tamaño de letra de la tabla" min="8" max="200" :value="table.fontSize" @change="patchTable({ fontSize: Number($event.target.value) })" /></label><label class="space-y-1">Alineación de la tabla<select class="field text-xs" aria-label="Alineación de la tabla" :value="table.align" @change="patchTable({ align: $event.target.value })"><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></label></div>
                    <div class="grid grid-cols-2 gap-2"><label>Color del encabezado<input type="color" class="mt-1 h-8 w-full" :value="table.headerFill.slice(0,7)" @input="patchTable({ headerFill: $event.target.value })" /></label><label>Color del borde de la tabla<input type="color" class="mt-1 h-8 w-full" :value="table.borderColor.slice(0,7)" @input="patchTable({ borderColor: $event.target.value })" /></label></div>
                </section>
                <section v-if="item.type === 'connector'" class="space-y-3 rounded-xl border border-slate-200 p-3" aria-label="Conector">
                    <h3 class="font-semibold">Conector</h3>
                    <p class="text-[10px] leading-relaxed text-slate-500">{{ item.from && item.to ? 'Unido a dos elementos: sigue sus movimientos.' : 'Conector libre. Selecciona dos elementos y pulsa Añadir conector para unirlos.' }}</p>
                    <div class="grid grid-cols-2 gap-2"><label class="space-y-1">Trazado del conector<select class="field text-xs" aria-label="Trazado del conector" :value="item.route" @change="patch('route', $event.target.value)"><option value="straight">Recto</option><option value="elbow">En ángulo</option></select></label><label class="space-y-1">Flecha del conector<select class="field text-xs" aria-label="Flecha del conector" :value="item.arrow" @change="patch('arrow', $event.target.value)"><option value="none">Sin flecha</option><option value="end">Al final</option><option value="both">En ambos extremos</option></select></label></div>
                    <div class="grid grid-cols-2 gap-2"><label>Color de la línea<input type="color" class="mt-1 h-8 w-full" :value="(item.stroke || '#7c3aed').slice(0,7)" @input="patch('stroke',$event.target.value)" /></label><label>Grosor de la línea<input class="field mt-1 text-xs" type="number" min="1" max="40" :value="item.strokeWidth" @change="numeric('strokeWidth',$event)" /></label></div>
                </section>
                <section v-if="item.type === 'chart'" class="space-y-2 rounded-xl border border-violet-200 bg-violet-50 p-3"><h3 class="font-semibold">Gráfico con datos guardados</h3><p class="text-xs">Tabla {{ item.chart.binding.dataset.id }} · Revisión {{ item.chart.binding.dataset.revision }} fija</p><p class="break-all font-mono text-[10px]">{{item.chart.binding.dataset.sha256}}</p><button type="button" class="toggle bg-white" @click="emit('edit-chart')">Editar configuración y datos del gráfico</button></section><div class="grid grid-cols-2 gap-2"><label v-for="field in [{key:'x',label:'Posición X'},{key:'y',label:'Posición Y'},{key:'width',label:'Ancho del elemento'},{key:'height',label:'Alto del elemento'},{key:'scaleX',label:'Escala horizontal'},{key:'scaleY',label:'Escala vertical'},{key:'rotation',label:'Rotación'}]" :key="field.key" class="space-y-1">{{ field.label }}<input class="field text-xs" type="number" step="any" :value="Math.round(item[field.key] * 1000) / 1000" @change="numeric(field.key, $event)" /></label><label class="space-y-1">Opacidad<input class="field text-xs" type="number" min="0" max="1" step="0.05" :value="item.opacity" @change="numeric('opacity', $event)" /></label></div>
                <template v-if="!['image','video','group','chart','table','connector'].includes(item.type)">
                    <label class="flex items-center justify-between gap-2 font-medium">Color de relleno<input type="color" class="h-8 w-10 rounded border border-slate-200 p-0.5" :value="solid.slice(0,7)" @input="patch('fill', $event.target.value)" /></label>
                    <div class="flex flex-wrap gap-1.5"><button v-for="color in colors" :key="color" type="button" class="h-6 w-6 rounded-full border border-slate-200" :style="{ background: color }" :aria-label="`Aplicar color ${color}`" @click="patch('fill', color)" /></div>
                    <label class="flex items-center gap-2"><input type="checkbox" :checked="typeof item.fill === 'object'" @change="patch('fill', $event.target.checked ? {type:'linear',angle:45,stops:[{offset:0,color:solid},{offset:1,color:'#ffffff'}]} : solid)" />Degradado</label>
                    <div v-if="typeof item.fill === 'object'" class="grid grid-cols-3 gap-2"><label>Inicio<input type="color" class="mt-1 h-8 w-full" :value="solid.slice(0,7)" @input="gradient('start',$event.target.value)" /></label><label>Final<input type="color" class="mt-1 h-8 w-full" :value="item.fill.stops.at(-1).color.slice(0,7)" @input="gradient('end',$event.target.value)" /></label><label>Ángulo<input type="number" class="field mt-1 text-xs" min="-360" max="360" :value="item.fill.angle" @change="gradient('angle',$event.target.value)" /></label></div>
                    <div class="grid grid-cols-2 gap-2"><label>Color del borde<input type="color" class="mt-1 h-8 w-full" :value="item.stroke || '#000000'" @input="patch('stroke',$event.target.value)" /></label><label>Grosor del borde<input class="field mt-1 text-xs" type="number" min="0" max="1000" :value="item.strokeWidth" @change="numeric('strokeWidth',$event)" /></label></div>
                    <label v-if="item.type === 'rect'" class="block space-y-1">Esquinas redondeadas<input type="number" class="field text-xs" min="0" max="16000" :value="item.radius" @change="numeric('radius',$event)" /></label>
                </template>
                <template v-if="['image','video'].includes(item.type)">
                    <h3 class="font-semibold">Recorte y filtros</h3><div class="grid grid-cols-2 gap-2"><label v-for="key in ['cropX','cropY']" :key="key">{{ key === 'cropX' ? 'Recorte X' : 'Recorte Y' }}<input type="number" class="field mt-1 text-xs" min="0" max="32000" :value="item[key]" @change="numeric(key,$event)" /></label></div>
                    <label v-for="field in [{key:'brightness',label:'Brillo'},{key:'contrast',label:'Contraste'},{key:'saturation',label:'Saturación'},{key:'blur',label:'Desenfoque'}]" :key="field.key" class="block space-y-2">{{ field.label }}<input type="range" class="w-full accent-violet-600" :min="field.key === 'blur' ? 0 : -1" max="1" step="0.05" :value="item.filters?.[field.key] ?? 0" @change="filter(field.key,Number($event.target.value))" /></label>
                    <div class="flex flex-wrap gap-3"><label v-for="field in [{key:'grayscale',label:'Grises'},{key:'sepia',label:'Sepia'},{key:'invert',label:'Invertir'}]" :key="field.key" class="flex items-center gap-1.5"><input type="checkbox" :checked="item.filters?.[field.key]" @change="filter(field.key,$event.target.checked)" />{{ field.label }}</label></div>
                </template>
                <template v-if="item.type === 'image'">
                    <div class="space-y-3 border-t border-slate-100 pt-4"><h3 class="font-semibold">Máscara y fondo</h3><label class="block space-y-1">Máscara de imagen<select class="field text-xs" aria-label="Máscara de imagen" :value="item.mask?.type ?? 'none'" @change="chooseMask($event.target.value)"><option value="none">Sin máscara</option><option value="ellipse">Elipse</option><option value="rounded_rect">Rectángulo redondeado</option></select></label><label v-if="item.mask?.type === 'rounded_rect'" class="block space-y-1">Radio de la máscara<input type="number" class="field text-xs" aria-label="Radio de la máscara" min="0" max="16000" step="1" :value="item.mask.radius" @change="patch('mask',{ type:'rounded_rect', radius:Number($event.target.value) })" /></label><button type="button" class="w-full rounded-lg border border-violet-200 bg-violet-50 px-3 py-2 text-xs font-medium text-violet-800 hover:bg-violet-100 disabled:opacity-50" :disabled="imageBusy" @click="emit('remove-background',item.asset_id)">Quitar fondo de imagen seleccionada</button><p class="text-[10px] leading-relaxed text-slate-500">Genera otra imagen para conservar el original y sus ajustes.</p></div>
                </template>
                <template v-if="item.type === 'video'"><h3 class="font-semibold">Vídeo · vista de fotograma</h3><div class="grid grid-cols-2 gap-2"><label>Inicio (segundos)<input type="number" class="field mt-1 text-xs" min="0" step="0.1" :value="item.trimStart" @change="numeric('trimStart',$event)" /></label><label>Fin (segundos)<input type="number" class="field mt-1 text-xs" min="0" step="0.1" :value="item.trimEnd" @change="patch('trimEnd',$event.target.value === '' ? null : Number($event.target.value))" /></label></div><label class="block space-y-1">Volumen<input type="range" min="0" max="1" step="0.05" class="w-full accent-violet-600" :value="item.volume" @change="numeric('volume',$event)" /></label><label class="flex items-center gap-2"><input type="checkbox" :checked="item.muted" @change="patch('muted',$event.target.checked)" />Silenciar vídeo</label></template>
                <div class="border-t border-slate-100 pt-4"><label class="flex items-center gap-2"><input type="checkbox" :checked="!!item.shadow" @change="patch('shadow',$event.target.checked ? {color:'#00000066',blur:12,offsetX:0,offsetY:4} : null)" />Sombra</label><div v-if="item.shadow" class="mt-3 grid grid-cols-2 gap-2"><label>Color de sombra<input type="color" class="mt-1 h-8 w-full" :value="item.shadow.color.slice(0,7)" @input="shadow('color',$event.target.value)" /></label><label v-for="field in [{key:'blur',label:'Difusión'},{key:'offsetX',label:'Desplazamiento X'},{key:'offsetY',label:'Desplazamiento Y'}]" :key="field.key">{{ field.label }}<input class="field mt-1 text-xs" type="number" :value="item.shadow[field.key]" @change="shadow(field.key,Number($event.target.value))" /></label></div></div>
                <div class="flex gap-2"><button type="button" class="toggle" @click="emit('action','flip','x')">Voltear horizontal</button><button type="button" class="toggle" @click="emit('action','flip','y')">Voltear vertical</button></div>
                <div class="grid grid-cols-3 gap-2"><button v-for="align in [{key:'left',label:'Izquierda'},{key:'center',label:'Centro'},{key:'right',label:'Derecha'},{key:'top',label:'Arriba'},{key:'middle',label:'Medio'},{key:'bottom',label:'Abajo'}]" :key="align.key" type="button" class="toggle" :aria-label="`Alinear ${align.label.toLowerCase()}`" @click="emit('action','align',align.key)">{{ align.label }}</button></div>
            </fieldset>
        </template>
    </section>
</template>
<style scoped>.toggle{border:1px solid #e2e8f0;border-radius:.5rem;padding:.5rem;font-size:11px}.toggle:hover{background:#f8fafc}.toggle[aria-pressed=true]{background:#ede9fe;border-color:#c4b5fd;color:#6d28d9}</style>
